sys_script_include.script:
var CLMAgentProcessor = Class.create();

CLMAgentProcessor.prototype = {

    processCompany: function(companyName) {

        try {

            var request = new sn_ws.RESTMessageV2();

            request.setEndpoint(gs.getProperty('glide.servlet.uri') +
                'api/sn_aia/agenticai/v1/agent/id/e8380286973f7a90be31fa17f053af49');

            request.setHttpMethod('POST');

            request.setRequestHeader('Content-Type', 'application/json');
            request.setRequestHeader('Accept', 'application/json');

            var body = {
                request_id: gs.generateGUID(),
                metadata: {},
                inputs: [{
                    content_type: "text",
                    content: companyName
                }]
            };

            request.setRequestBody(JSON.stringify(body));

            var response = request.execute();

gs.info("Status: " + response.getStatusCode());
gs.info("Body: " + response.getBody());
            var responseBody = response.getBody();

            gs.info(responseBody);

            // Wait a few seconds for AI Agent record creation
            gs.sleep(5000);

            var gr = new GlideRecord('x_birl3_clm_customer_performance');
            gr.addQuery('company_name', companyName);
            gr.orderByDesc('sys_created_on');
            gr.setLimit(1);
            gr.query();

            if (gr.next()) {

                return {
                    success: true,

                    company_name:
                    gr.getValue('company_name'),

                    current_stock_price:
                    gr.getValue('current_stock_price'),

                    market_stock_insight:
                    gr.getValue('market_stock_insight'),

                    key_news_highlights:
                    gr.getValue('key_news_highlights'),

                    final_recommendation:
                    gr.getValue('final_recommendation'),

                    created_on:
                    gr.getDisplayValue('sys_created_on')
                };
            }

            return {
                success: false,
                message: 'No assessment created'
            };

        } catch (e) {

            gs.error(e);

            return {
                success: false,
                message: e.message
            };
        }
    },

    type: 'CLMAgentProcessor'
};
